// Generates packages/core/src/unicode-font-data.ts: which characters the Noto fonts used for text boxes in other
// alphabets can show, which of the font's files (subsets) has each, and its advance width. core uses this to lay
// text out identically in the editor and in the saved PDF, where only the letters used are embedded.
//   pnpm gen-font-data
// A test (engine/test/unicode-text.test.ts) fails if the generated file ever disagrees with the font files.
import { readFileSync, writeFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import fontkit from '@cantoo/fontkit';
import { UNICODE_FAMILIES, UNICODE_SUBSETS, unicodeFontFile } from '../src/unicode-fonts';

const require = createRequire(import.meta.url);
const fileOf = (pkg: string, name: string) => join(dirname(require.resolve(`${pkg}/package.json`)), 'files', name);

type Font = { characterSet: number[]; unitsPerEm: number; glyphForCodePoint(cp: number): { id: number; advanceWidth: number } };

/** Combining marks would need a shaping engine to sit on their letter; text is NFC-normalised so few are needed. */
const isMark = (cp: number) => /\p{M}/u.test(String.fromCodePoint(cp));

// family -> code point -> [subset index, width in 1/1000 em]
const covered = new Map<string, Map<number, [number, number]>>();
for (const [family, pkg] of Object.entries(UNICODE_FAMILIES)) {
  const map = new Map<number, [number, number]>();
  UNICODE_SUBSETS.forEach((subset, si) => {
    const font = fontkit.create(readFileSync(fileOf(pkg, unicodeFontFile(pkg, subset)))) as unknown as Font;
    for (const cp of font.characterSet) {
      if (cp < 32 || (cp >= 0x7f && cp < 0xa0) || isMark(cp) || map.has(cp)) continue;
      const g = font.glyphForCodePoint(cp);
      if (g.id === 0) continue;
      map.set(cp, [si, Math.round((g.advanceWidth * 1000 * 1000) / font.unitsPerEm) / 1000]);
    }
  });
  covered.set(family, map);
}

// Only characters every family can show, so changing a box's font never loses any.
const families = [...covered.keys()];
const all = [...covered.get(families[0]!)!.keys()].filter((cp) => families.every((f) => covered.get(f)!.has(cp))).sort((a, b) => a - b);

/** Runs of consecutive code points that come from the same file: [first code point, subset, width, width, ...]. */
function runs(family: string): (number | string)[][] {
  const map = covered.get(family)!;
  const out: (number | string)[][] = [];
  let run: (number | string)[] | undefined;
  let next = -1;
  for (const cp of all) {
    const [si, w] = map.get(cp)!;
    if (!run || cp !== next || run[1] !== si) out.push((run = [cp, si]));
    run.push(w);
    next = cp + 1;
  }
  return out;
}

const lines = [
  "// GENERATED by packages/engine/scripts/gen-unicode-font-data.ts from the Noto font files. Do not edit.",
  '',
  '/** For each family: runs of [first code point, subset index, advance width in 1/1000 em for each code point]. */',
  'export const UNICODE_RUNS = {',
  ...families.map((f) => `  ${f}: ${JSON.stringify(runs(f))},`),
  '} as const satisfies Record<string, readonly (readonly number[])[]>;',
  '',
];
const out = fileURLToPath(new URL('../../core/src/unicode-font-data.ts', import.meta.url));
writeFileSync(out, lines.join('\n'));
console.log(`wrote ${out}: ${all.length} characters x ${families.length} families`);
